declare const __PWA__: boolean;

// Reload onto a new version only right after opening, so nobody loses what they were doing.
// Later updates are picked up on the next open.
const RELOAD_WINDOW_MS = 10_000;

// The service worker (sw.js) is generated by vite-plugin-pwa for hosted builds only.
// Registered after load so it never competes with first paint.
export function registerServiceWorker(): void {
  if (!import.meta.env.PROD || typeof __PWA__ === 'undefined' || !__PWA__) return;
  if (!('serviceWorker' in navigator)) return;
  // A controller at startup means a version is already installed; a change of controller then
  // means a newer version just took over, so show it instead of the copy already on screen.
  const hadController = !!navigator.serviceWorker.controller;
  let reloaded = false;
  navigator.serviceWorker.addEventListener('controllerchange', () => {
    if (!hadController || reloaded || performance.now() > RELOAD_WINDOW_MS) return;
    reloaded = true;
    window.location.reload();
  });
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('./sw.js', { scope: './' }).catch(() => {
      // Offline support is a progressive enhancement; the app works without it.
    });
  });
}
